/**
 * CLI for the auto-generated-username cleanup migration (drops the random
 * suffix so `name.regno_a1b2c3` becomes `name.regno`, for accounts that never
 * customized their username).
 *
 *   npm run migrate:usernames -- --dry-run     # report what WOULD happen, write nothing
 *   npm run migrate:usernames                  # run the migration (safe to re-run)
 *
 * Reads MONGO_URL from the environment / backend/.env, exactly like the server.
 */
import "dotenv/config";
import mongoose from "mongoose";
import { migrateAutoGeneratedUsernames } from "../src/migrations/usernames.migration.js";

const args = new Set(process.argv.slice(2));
const dryRun = args.has("--dry-run");

const log = (msg) => console.log(`[migrate-usernames] ${msg}`);

const main = async () => {
  if (!process.env.MONGO_URL) {
    console.error("MONGO_URL is not set. Aborting.");
    process.exit(1);
  }

  await mongoose.connect(process.env.MONGO_URL);
  const db = mongoose.connection.db;
  log(`Connected to database "${db.databaseName}"${dryRun ? " (DRY RUN — nothing will be written)" : ""}`);

  const stats = await migrateAutoGeneratedUsernames(db, { dryRun, log });
  log(`Result: ${JSON.stringify(stats, null, 2)}`);

  return stats.failed.length > 0 ? 1 : 0;
};

main()
  .then((code) => mongoose.disconnect().then(() => process.exit(code)))
  .catch(async (err) => {
    console.error("Migration crashed:", err);
    await mongoose.disconnect().catch(() => {});
    process.exit(1);
  });
